import{_ as a,c as e,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易义海撮要卷十一","description":"周易义海撮要 - 周易义海撮要卷十一","frontmatter":{"title":"周易义海撮要卷十一","description":"周易义海撮要 - 周易义海撮要卷十一"},"headers":[],"relativePath":"zh/classics/yihai-cuoyao/012.md","filePath":"zh/classics/yihai-cuoyao/012.md"}'),i={name:"zh/classics/yihai-cuoyao/012.md"};function o(c,p,r,_,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="周易义海撮要卷十一" tabindex="-1">周易义海撮要卷十一 <a class="header-anchor" href="#周易义海撮要卷十一" aria-label="Permalink to “周易义海撮要卷十一”">​</a></h1><p>钦定四库全书</p><p>宋李衡撰</p><p>乾刚坤柔，</p><p>刚柔，体也，健顺用也。 龚：比乐师忧。</p><p>比则相亲，师则在险。 龚：动众则忧。 注：</p><p>临、观之义，或与或求，以上临下，以下临上，以己观物，以物观己。 龚：以我临物，物来观我。 注：防民之道，贵于中正。中正则可以风化天下，或为下之所相与，或为下之来求也。 胡 屯：见而不失其居。</p><p>不见则不足以济众，不居则不足以为主。 龚：君子以经纶，故曰「见磐桓，利居贞」，故曰「不失其居」。 坡：经纶之时，必须利建侯以安天下，使天下之人皆安其居，不失其所。 胡：蒙杂而著，</p><p>杂者未知所定，求发其蒙，则终得所定。 注：得贤者以发明之，则无所错杂而自著见。 胡：震，起也；艮，止也。</p><p>起者，生于动，阳在下也；止者，生于静，阳在上也。 龚：损益，盛衰之始也。</p><p>损之终必益，则损者乃盛之始；益之终必损，则益者乃衰之始。损益者，其渐也；盛衰者，其成也。 龚：大畜，时也。</p><p>莫非时也，而「大畜」者，时之盛也。君有以畜，臣有以进贤者尚健者。止：古之君子所以欲得时者如此而已。 龚：因时而畜，故能大也。 注：以艮畜乾而可者，时也。 坡：无妄，灾也。</p><p>妄作凶者，人也；无妄灾者，天也。 龚：以乾行震而不可者，灾也。六三行人得牛，邑人之灾。又曰：「无妄之药，不可试也。」 坡：萃聚而升不来也。</p><p>聚而正，故往。巽而顺，故不来。 龚：来，还也。方在上升，故不来也。 注：易以上为往，下为来。泽上于地，萃聚于下。地中生木，升之于上也。 坡：谦轻而豫怠也。</p><p>意在卑，则不自重；意在乐，则不自勤。 龚：锐于有为者，折节以下人。安于无事者，知乐而不忧。 坡：噬嗑，食也。除间则为颐。 龚：自三至五，皆以相噬为事，躁于食者也。 坡：雷电相合，如颐中啮去刚梗之物，故言食也。 胡 贲，无色也。</p><p>色色者，无色。 龚：饰贵合众，无定色。 注：自初至四，正不受污，安于无色。 坡：兑见而巽伏也。</p><p>说在外，入自内。 龚：兑贵显说，巽贵卑顺。 注：</p><p>随，无故也。蛊则饰也。惟时故无故不可随，故欲饰。 龚：随时之宜，不系于故。随则有事，故受之以蛊。饰，治也。 注：故，事也。饰，修也。以随时为安，故其象曰：「君子向晦入宴息。」以修惰为安，故其象曰：「君子以振民育德。」 坡：剥，烂也；复，反也。</p><p>剥之极，虽硕果亦烂。复之初，虽阴亦反。 龚：晋，昼也。明夷，诛也。</p><p>日未及中，故不亢，而锡马蕃庶，赏可知也。明者伤，则阍者不可久，故上九复入于地，诛可知也。 龚。 昼日三接，故曰昼，得其大首，故曰诛。 坡：井通而困相遇也。</p><p>居其所而迁，刚揜而无所逃。 龚。 物所通用而不吝，安于所遇而不滥。 注：井居其所而人即之，困欲行而遇刚揜。 坡：井以济人为德，故云通。物既久困，必须遇贤德以出之。 胡 咸，速也。恒，久也。化不待久，久莫如恒。 龚。 物之相应，莫速如咸。 注：涣，离也。节，止也。</p><p>涣所以散之，节所以制之。 龚。 解，缓也。蹇，难也。蹇则急，解则易。 龚。 睽，外也；家人，内也。</p><p>「二女同居，其志不同行」，外也。「利女贞」，内也。 龚：相疏，外也。 注：否、泰，反其类也。</p><p>阳与阳，阴与阴，类也。否、泰以其类反，故爻言汇言畴。 龚。</p><p>大壮则止，遁则退也。</p><p>君子非用壮也，势足以胜小人则止；非好遁也，势不足以胜小人则退。 龚：大正则小人止，小人亨则君子退。</p><p>大有，众也。同人，亲也。有则有上下，故分众寡。同则无彼此，有亲而已。 龚：亲则于众有所择。 坡：</p><p>革，去故也。鼎，取新也。</p><p>变而有之，当而利用。 龚：</p><p>小过，过也。中孚，信也。</p><p>大者之过，所谓分也。小者之过，所谓过也。中而不孚，孚而不中，皆非所谓信也。 龚：阴在外，据用事之地。阴在内，不据用事之地。 坡：小过者，人情小有过差。中孚者，信及天下。 胡：</p><p>丰，多故也。亲寡，旅也。</p><p>亲寡而为旅，自丰而多故也。 龚：高者惧危，满者戒盈，丰大者多忧故也。 注：丰以盛大而多忧，旅以寡弱而相亲。 坡：离上而坎下也。</p><p>炎上润下，言其性也。 龚：小畜，寡也。柔为君，故大有则众。柔为臣，故小畜则寡。 龚：不足以兼济也。 注：</p><p>履，不处也。需，不进也。</p><p>以往为义，故不处。以须为义，故不进。 龚：履卦阳爻，皆不以处尊位为吉。需畏险而止。 注：履以谦为主，随人而行。需待时而往。 胡。 讼，不亲也，</p><p>非同人也，故不亲。 龚。 相违也。 坡。 大过，颠也，</p><p>本末柔也。 注：上下相陵，本末颠错。 胡。</p><p>姤，遇也，柔遇刚也。渐，女归待男行也。</p><p>柔遇刚，非困之相遇。女归待男行，非晋之进 龚。 天下会遇之时，男女之行，必以渐进，然后成夫妇之道。 胡。 颐，养正也。颐，正吉。既济，定也。亨小故曰定。止者，自止。定者，止之而后定也。 龚。 水火相济，君臣相得，而天下大治，物性一定之时。</p><p>归妹，女之终也。未济，男之穷也。</p><p>女始于笄，终于嫁，故曰「归妹，女之终」。离，中女而趋上，坎，中男而趋下，非相求也，故曰「男之穷也」。 龚。 刚柔失位，故穷。</p><p>夬，决也，刚决柔也。君子道长，小人道忧也。</p><p>刚长乃终而复于乾也。杂卦自乾、坤至需、讼，皆两两相从，而明相反之义。自大过以下八卦，非相从之次，今改之。初上者，本末之地，以阳居之则正，以阴居之则颠，故曰：「颐，养正也；大过，颠也。姤，遇也，柔遇刚也。</p><p>夬，决也，刚决柔也，君子道长，小人道忧也。」艮下巽上为渐，男下女，非其正也，故曰：渐，女归待男行也。兑下震上为归妹，男女之正也，当以是终，故曰：「归妹，女之终也」。离下坎上为既济，男女之正也，故曰：「既济，定也」。坎下离上为未济，男失其位，穷之道也，故曰：「未济，男之穷也」。如此，则相从之次，相反之义，涣然若合符节矣。 坡</p><p>周氏以六门分序卦，如乾之次坤，泰之次否，为天道；如讼必有师，师必有比之类，为人事；因小畜生履，因履故通等，为相因；如遁极反壮，动竟归止等，为相反；如大有、需谦，蒙稚待养，为相须；如贲尽生剥，进极致伤等，是相病门。韩康伯云：「序卦之所明，明非易之缊也。」盖因卦之次，托象以明义，不取深缊之义，故曰：「非易之缊」，故以取其人理也。今验六十四卦，二二相偶，非覆即变。覆者，表里视之，遂成两卦，屯蒙、需、讼、师、比之类是也。变者，反复唯成一卦，则变以对之，乾、坤、坎、离、大过、颐、中孚、小过之类是也。且圣人本定先后，若元用孔子序卦之意，则不应非覆即变。然则康伯之言为不虚矣。 孔</p><p>易之为名，有易之者，有相易者。易之者，一言也，相易者，两言也。故自一卦则内外上下相易，自乾、坤以至坎、离，自咸、恒以至既济、未济，则两卦相易，虽名有六十四，而反对相成，实三十有二卦也。反对者，自两卦而言也，若杂卦是也。积两卦而相易，若序卦是也。杂卦则反对而不相通，序卦则相通而为一。说卦者，各因其才也，故其名辨而不杂。序卦则以序而言之也，故故其事类而相通。</p><p>上经始于乾、坤，终于坎、离，言天道也，故卦象亦以体为主，若天行、地势、水瀳、至明、两作是也。下经始于咸、恒，终于既济、未济，言人道也，故卦象亦以用为主，若瀳雷、兼山、随风、丽泽是也。言天道，故曰有天地，然后万物生焉，未及人道也。言人道，故曰</p><p>「有天地，然后有万物，以至礼义有所错」也。 龚：周易义海撮要卷十一。</p>',49)])])}const m=a(i,[["render",o]]);export{h as __pageData,m as default};
